__device__ uint32_t fieldInverse(uint32_t x){uint64_t a=x,r=1;for(uint32_t e=2147483645;e;e>>=1,a=a*a%2147483647)if(e&1)r=r*a%2147483647;return uint32_t(r);}
__device__ void put(uint32_t *v,uint32_t at,uint64_t x){for(int i=0;i<4;++i)v[at+i]=(x>>(16*i))&65535;}
__device__ void carry(uint32_t*v,uint32_t at,uint64_t x,uint32_t step=8){for(int i=0;i<3;++i){step=(((x>>(16*i))&65535)+step)>>16;v[at+i]=step;}}
__device__ void clock(uint32_t*v,uint32_t at,StwoRv64ServiceState s,const StwoRv64BulkCall&c,uint32_t*status){v[at]=s.epoch;v[at+1]=s.tick&65535;v[at+2]=s.tick>>16;if(s.epoch>c.epoch||(s.epoch==c.epoch&&s.tick>=c.tick)){atomicOr(status,1u);return;}uint32_t gap=s.epoch==c.epoch?c.tick-s.tick-1:c.epoch-s.epoch-1;v[at+3]=s.epoch==c.epoch;v[at+4]=gap&65535;v[at+5]=s.epoch==c.epoch?gap>>16:0;}
__device__ void after(uint32_t*v,uint32_t at,const StwoRv64BulkCall&c){v[at]=c.epoch;v[at+1]=c.tick&65535;v[at+2]=c.tick>>16;}
__device__ void count(uint32_t*counts,uint32_t x,uint32_t*status){if(x>=65536){atomicOr(status,2u);return;}if(atomicAdd(counts+x,1u)>=0x7ffffffeu)atomicOr(status,4u);}
__device__ void ckcounts(uint32_t*counts,const uint32_t*v,uint32_t at,uint32_t*status){count(counts,v[at+4],status);count(counts,v[at+5],status);count(counts,256*v[at+5],status);}
__device__ void bytescounts(uint32_t*counts,uint32_t lo,uint32_t hi,uint32_t*status){count(counts,lo,status);count(counts,256*lo,status);count(counts,hi,status);}
__device__ uint32_t next(uint32_t p,uint32_t b){return p?p-1:(b>=0x60&&b<=0x7f?b-0x5f:0);}
__global__ void analyze(const StwoRv64BulkCall*calls,uint32_t nc,const StwoRv64BulkWord*words,uint32_t nw,uint32_t*pending,uint32_t np,uint32_t*hist,uint32_t*status){uint32_t k=blockIdx.x*blockDim.x+threadIdx.x;if(k>=nc)return;auto c=calls[k];if(c.op!=3)return;uint32_t n=c.len/8,p=0;if(uint64_t(c.first_word)+n>nw||uint64_t(c.first_scan)+(n+7)/8>np){atomicOr(status,8u);return;}for(uint32_t j=0;j<n;++j){if(!(j%8))pending[c.first_scan+j/8]=p;uint64_t w=words[c.first_word+j].src.value;for(int b=0;b<8;++b){uint32_t x=(w>>(8*b))&255;if(atomicAdd(hist+256*p+x,1u)>=0x7ffffffeu)atomicOr(status,4u);p=next(p,x);}}}
__device__ void ranges(uint32_t kind,const uint32_t*v,uint32_t*h,uint32_t*s){
 if(kind==0){using namespace L::desc;count(h,v[tick_low],s);count(h,v[tick_high],s);count(h,256*v[tick_high],s);count(h,v[fill_low],s);count(h,256*v[fill_low],s);count(h,v[fill_high],s);count(h,256*v[fill_high],s);count(h,v[len_q0],s);for(int k=0;k<3;++k)ckcounts(h,v,clocks+6*k,s);}
 else if(kind==1){ckcounts(h,v,L::copy::dst_clock,s);ckcounts(h,v,L::copy::src_clock,s);}
 else if(kind==2)ckcounts(h,v,L::set::dst_clock,s);
 else if(kind==3){ckcounts(h,v,L::ucopy::dst_clock,s);ckcounts(h,v,L::ucopy::src_clock,s);for(int k=0;k<4;++k)bytescounts(h,v[L::ucopy::bytes+2*k],v[L::ucopy::bytes+2*k+1],s);}
 else if(kind==4){using namespace L::cdesc;count(h,v[tick_low],s);count(h,v[tick_high],s);count(h,256*v[tick_high],s);count(h,v[len_q0],s);for(int k=0;k<4;++k)ckcounts(h,v,clocks+6*k,s);}
 else if(kind==5){using namespace L::cmp;ckcounts(h,v,a_clock,s);ckcounts(h,v,b_clock,s);bytescounts(h,v[alo],v[ahi],s);bytescounts(h,v[blo],v[bhi],s);count(h,v[gap],s);}
 else if(kind==6){using namespace L::jdesc;count(h,v[tick_low],s);count(h,v[tick_high],s);count(h,256*v[tick_high],s);count(h,v[len_q0],s);count(h,v[code_q],s);count(h,64*v[code_q],s);for(int k=0;k<3;++k)ckcounts(h,v,clocks+6*k,s);}
 else if(kind==7){for(int k=0;k<8;++k)ckcounts(h,v,L::jscan::clocks+6*k,s);ckcounts(h,v,L::jscan::wclock,s);}}
__host__ __device__ uint32_t width(uint32_t k){const uint32_t w[]={48,41,24,56,61,59,45,287,1};return w[k];}
__global__ void witness(StwoRv64BulkWitness job){uint32_t logical=blockIdx.x*blockDim.x+threadIdx.x,n=1u<<job.log;if(logical>=n)return;uint32_t v[287]={0};
 if(job.kind==8){if(logical<8448)v[0]=job.jump_counts[logical];}
 else if(logical<job.count){auto row=job.rows[logical];if(row.call>=job.call_count){atomicOr(job.status,16u);return;}auto c=job.calls[row.call];uint32_t j=row.index;uint64_t count=c.len/8;StwoRv64BulkWord w={};if(job.kind==1||job.kind==2||job.kind==3||job.kind==5){if(row.word>=job.word_count){atomicOr(job.status,16u);return;}w=job.words[row.word];}
 if(job.kind==0){using namespace L::desc;v[active]=1;v[set]=c.op;put(v,pointer,c.pointer);carry(v,carry8,c.pointer);carry(v,carry16,c.pointer+8);after(v,epoch,c);put(v,dst,c.dst);put(v,word1,c.word1);v[len_q0]=(c.len&65535)/8;v[len_l1]=(c.len>>16)&65535;v[fill_low]=c.word1&255;v[fill_high]=(c.word1>>8)&255;for(int k=0;k<3;++k){clock(v,clocks+6*k,c.packet[k],c,job.status);v[writable+k]=c.packet[k].rights>>1;}}
 else if(job.kind==1){using namespace L::copy;v[active]=1;v[start]=j==0;after(v,epoch,c);v[remaining]=count-j;put(v,dst,c.dst+8*j);put(v,src,c.word1+8*j);if(j){carry(v,dst_carry,c.dst+8*(j-1));carry(v,src_carry,c.word1+8*(j-1));}put(v,value,w.src.value);put(v,dst_before,w.dst.value);clock(v,dst_clock,w.dst,c,job.status);clock(v,src_clock,w.src,c,job.status);v[src_writable]=w.src.rights>>1;}
 else if(job.kind==2){using namespace L::set;v[active]=1;v[start]=j==0;after(v,epoch,c);v[remaining]=count-j;put(v,dst,c.dst+8*j);if(j)carry(v,dst_carry,c.dst+8*(j-1));v[fill]=c.word1&255;put(v,dst_before,w.dst.value);clock(v,dst_clock,w.dst,c,job.status);}
 else if(job.kind==3){using namespace L::ucopy;uint32_t sh=c.word1&7;uint64_t base=c.word1&~7ULL;if(!sh){atomicOr(job.status,32u);return;}v[active]=1;v[start]=j==0;after(v,epoch,c);v[remaining]=count+1-j;put(v,dst,c.dst+8*(j?j-1:0));put(v,src,base+8*j);if(j>=2)carry(v,dst_carry,c.dst+8*(j-2));if(j==1)carry(v,dst_carry,c.dst,0);if(j)carry(v,src_carry,base+8*(j-1));v[sel+sh-1]=1;for(int b=0;b<8;++b)v[bytes+b]=(w.src.value>>(8*b))&255;if(j){if(!row.word){atomicOr(job.status,16u);return;}put(v,out,(job.words[row.word-1].src.value>>(8*sh))|(w.src.value<<(64-8*sh)));put(v,dst_before,w.dst.value);clock(v,dst_clock,w.dst,c,job.status);}clock(v,src_clock,w.src,c,job.status);v[src_writable]=w.src.rights>>1;}
 else if(job.kind==4){using namespace L::cdesc;v[active]=1;put(v,pointer,c.pointer);carry(v,carry8,c.pointer);carry(v,carry16,c.pointer+8);carry(v,carry24,c.pointer+16);after(v,epoch,c);put(v,a,c.dst);put(v,b,c.word1);v[len_q0]=(c.len&65535)/8;v[len_l1]=(c.len>>16)&65535;v[len_inv]=fieldInverse(count);for(int k=0;k<4;++k)clock(v,clocks+6*k,c.packet[k],c,job.status);for(int k=0;k<3;++k)v[writable+k]=c.packet[k].rights>>1;put(v,result_before,c.packet[3].value);v[neg]=c.result<0;v[pos]=c.result>0;}
 else if(job.kind==5){using namespace L::cmp;v[active]=1;v[start]=j==0;after(v,epoch,c);v[remaining]=count-j;v[last]=j+1==c.examined;v[is_one]=count-j==1;if(count-j!=1)v[inv]=fieldInverse(count-j-1);put(v,a,c.dst+8*j);put(v,b,c.word1+8*j);if(j){carry(v,a_carry,c.dst+8*(j-1));carry(v,b_carry,c.word1+8*(j-1));}uint64_t x=w.dst.value,y=w.src.value;put(v,va,x);put(v,vb,y);clock(v,a_clock,w.dst,c,job.status);clock(v,b_clock,w.src,c,job.status);v[a_writable]=w.dst.rights>>1;v[b_writable]=w.src.rights>>1;if(x!=y){uint32_t by=(__ffsll(x^y)-1)/8,limb=by/2,dx=(x>>(8*by))&255,dy=(y>>(8*by))&255;v[diff]=1;v[limbsel+limb]=1;v[hb]=by&1;v[lt]=dx<dy;v[alo]=(x>>(16*limb))&255;v[ahi]=(x>>(16*limb+8))&255;v[blo]=(y>>(16*limb))&255;v[bhi]=(y>>(16*limb+8))&255;v[da]=dx;v[db]=dy;v[gap]=(dx<dy?dy-dx:dx-dy)-1;}}
 else if(job.kind==6){using namespace L::jdesc;v[active]=1;put(v,pointer,c.pointer);carry(v,carry8,c.pointer);carry(v,carry16,c.pointer+8);after(v,epoch,c);v[code_q]=(c.dst&65535)/64;for(int i=0;i<3;++i)v[code+i]=(c.dst>>(16*(i+1)))&65535;v[len_q0]=(c.len&65535)/8;v[len_l1]=(c.len>>16)&65535;put(v,bitmap,c.word1);for(int k=0;k<3;++k){clock(v,clocks+6*k,c.packet[k],c,job.status);v[writable+k]=c.packet[k].rights>>1;}}
 else if(job.kind==7){using namespace L::jscan;uint32_t remain=count-8*j,valid=remain<8?remain:8;if(uint64_t(c.first_word)+count+j>=job.word_count||c.first_scan+j>=job.pending_count){atomicOr(job.status,16u);return;}v[active]=1;v[start]=j==0;v[last]=remain<=8;after(v,epoch,c);v[remaining]=remain;put(v,code,c.dst+64*j);put(v,bitmap,c.word1+8*j);if(j){carry(v,code_carry,c.dst+64*(j-1),64);carry(v,bitmap_carry,c.word1+8*(j-1));}for(uint32_t k=1;k<valid;++k)v[L::jscan::valid+k-1]=1;uint32_t p=job.pending[c.first_scan+j];v[L::jscan::pending]=p;for(uint32_t k=0;k<valid;++k){auto s=job.words[c.first_word+8*j+k].src;clock(v,clocks+6*k,s,c,job.status);v[writable+k]=s.rights>>1;for(int b=0;b<8;++b){uint32_t at=8*k+b,x=(s.value>>(8*b))&255;v[bytes+at]=x;v[jd+at]=p==0&&x==0x5b;p=next(p,x);v[L::jscan::pending+at+1]=p;}}auto s=job.words[c.first_word+count+j].dst;put(v,before,s.value);clock(v,wclock,s,c,job.status);}
 }
 ranges(job.kind,v,job.range16,job.status);uint32_t circle=logical&1?n-1-logical/2:logical/2,physical=__brev(circle)>>(32-job.log);for(uint32_t col=0;col<width(job.kind);++col)job.main[uint64_t(col)*n+physical]=v[col];}
}
