extern "C" int stwo_rv64_bulk_analyze_on(void*ctx,uint32_t lane,const StwoRv64BulkCall*c,uint32_t nc,const StwoRv64BulkWord*w,uint32_t nw,uint32_t*p,uint32_t np,uint32_t*h,uint32_t*s){using namespace stwo::cuda::rv64;Custody x(ctx,lane);if((nc&&!x.range(reinterpret_cast<const uint32_t*>(c),uint64_t(nc)*sizeof(*c)/4,false))||(nw&&!x.range(reinterpret_cast<const uint32_t*>(w),uint64_t(nw)*sizeof(*w)/4,false))||(np&&!x.range(p,np,true))||!x.range(h,8448,true)||!x.range(s,1,true))return x.status;if(nc)analyze<<<(nc+63)/64,64,0,x.stream>>>(c,nc,w,nw,p,np,h,s);return int(cudaPeekAtLastError());}
extern "C" int stwo_rv64_bulk_witness_on(void*ctx,uint32_t lane,const StwoRv64BulkWitness*j){using namespace stwo::cuda::rv64;if(!j||j->kind>8||j->log<5||j->log>26||j->count>(1u<<j->log))return int(cudaErrorInvalidValue);Custody x(ctx,lane);if((j->call_count&&!x.range(reinterpret_cast<const uint32_t*>(j->calls),uint64_t(j->call_count)*sizeof(*j->calls)/4,false))||(j->word_count&&!x.range(reinterpret_cast<const uint32_t*>(j->words),uint64_t(j->word_count)*sizeof(*j->words)/4,false))||(j->count&&j->kind!=8&&!x.range(reinterpret_cast<const uint32_t*>(j->rows),uint64_t(j->count)*4,false))||!x.range(j->main,uint64_t(width(j->kind))<<j->log,true)||!x.range(j->range16,65536,true)||!x.range(j->status,1,true)||(j->kind==7&&j->pending_count&&!x.range(j->pending,j->pending_count,false))||(j->kind==8&&!x.range(j->jump_counts,8448,false)))return x.status;witness<<<((1u<<j->log)+127)/128,128,0,x.stream>>>(*j);return int(cudaPeekAtLastError());}
